// User-manual content, authored in-repo (no DB). Rendered by
// app/(backend)/manual/**. Screenshots live in public/manual/screens/ and
// are (re)generated by scripts/capture-manual-screens.mjs — each `shot`
// block's `src` must match a file that script produces.
//
// Keep this file free of Prisma / server imports: the manual nav rail is a
// client component and imports MANUAL_TOPICS. Role -> audience mapping
// lives in app/lib/manual-access.ts instead.

export const MANUAL_AUDIENCES = ["user", "approver", "admin"] as const;
export type ManualAudience = (typeof MANUAL_AUDIENCES)[number];

export const AUDIENCE_LABEL: Record<ManualAudience, string> = {
  user: "For Requesters",
  approver: "For Approvers",
  admin: "For Administrators",
};

export const AUDIENCE_BLURB: Record<ManualAudience, string> = {
  user: "Everyone who raises and follows up on support tickets.",
  approver: "Department approvers who review tickets that need sign-off.",
  admin: "Administrators who triage tickets and manage master data.",
};

export type ManualBlock =
  | { type: "p"; text: string }
  | { type: "steps"; items: string[] }
  | { type: "bullets"; items: string[] }
  | { type: "note"; variant: "tip" | "info" | "warning"; text: string }
  | { type: "shot"; src: string; caption: string };

export type ManualSection = {
  heading: string;
  blocks: ManualBlock[];
};

export type ManualTopic = {
  slug: string;
  audience: ManualAudience;
  icon: string; // Bootstrap Icons class
  title: string;
  summary: string;
  sections: ManualSection[];
};

const SHOT = (name: string, caption: string): ManualBlock => ({
  type: "shot",
  src: `/manual/screens/${name}.png`,
  caption,
});

