export function topicsForAudience(audience: ManualAudience): ManualTopic[] {
  return MANUAL_TOPICS.filter((t) => t.audience === audience);
}

export function findTopic(audience: string, slug: string): ManualTopic | undefined {
  return MANUAL_TOPICS.find((t) => t.audience === audience && t.slug === slug);
}
